{- Chosen inputs for the three signature checks: the ways a check fails or
answers False, and valid signatures at the edges of its rules. A test's label
starts with its scheme, E for Ed25519, C for ECDSA and S for Schnorr, and tests
that share a label check the same rule.
-}
module Cells (cellTests) where

import Data.ByteString (ByteString)
import Data.ByteString qualified as BS
import Test.Tasty (TestTree, testGroup)
import Test.Tasty.HUnit (testCase, (@?=))
import Cardano.UPLC.Builtin (DefaultFun (..))
import Cardano.UPLC.Constant (Constant (..))
import Cardano.UPLC.Crypto qualified as Crypto
import Cardano.UPLC.Machine (
  EvalError (..),
  Params (..),
  SemanticsVariant (..),
  SignatureChecks (..),
  evaluateWith,
 )
import Cardano.UPLC.Name (DeBruijn)
import Cardano.UPLC.Term (Term (..))
import Hex (hex)

data Scheme = Ed25519 | Ecdsa | Schnorr
  deriving stock (Eq)

data Cell = Cell
  { row :: String
  , what :: String
  , scheme :: Scheme
  , key :: ByteString
  , message :: ByteString
  , signature :: ByteString
  , verdict :: Maybe Bool
  }

verifier :: Scheme -> ByteString -> ByteString -> ByteString -> Maybe Bool
verifier = \case
  Ed25519 -> select checkEd25519
  Ecdsa -> select checkEcdsa
  Schnorr -> select checkSchnorr
  where
    select field = maybe (\_ _ _ -> error "no verifier") id (field Crypto.libraryChecks)

cellTests :: TestTree
cellTests =
  testGroup
    "Chosen inputs"
    [ testGroup "Verdicts" [testCase (row c <> " " <> what c) (verifier (scheme c) (key c) (message c) (signature c) @?= verdict c) | c <- cells]
    , messageBound
    ]

-- A message of 65,536 bytes is accepted in every variant. One byte more is
-- accepted in A to C and fails in D and E, where the evaluator refuses it
-- before the verifier is asked.
messageBound :: TestTree
messageBound =
  testGroup "Message bound" $
    [ testCase (row c <> " " <> show v) (run v c @?= expected v c)
    | c <- cells
    , row c `elem` ["E20", "E21", "S14"]
    , v <- [minBound .. maxBound]
    ]
  where
    run v c = evaluateWith (Params v Crypto.libraryChecks) (call c)
    call c = foldl (Apply ()) (Builtin () (builtin c)) [con (key c), con (message c), con (signature c)]
    builtin c = if scheme c == Ed25519 then VerifyEd25519Signature else VerifySchnorrSecp256k1Signature
    con = Constant () . CByteString :: ByteString -> Term DeBruijn ()
    expected v c
      | BS.length (message c) > 65536 && v `elem` [VariantD, VariantE] = Left (BuiltinFailure (call c))
      | otherwise = Right (Constant () (CBool True))

